head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vCHAR1_CHANGED = "F";
scwin.vCHAR2_CHANGED = "F";
scwin.vCHAR3_CHANGED = "F";
scwin.vCHAR4_CHANGED = "F";
scwin.gLdMktTp = js_market;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.hideDebugCtrls();
        frame.width = "980";
        // fn_SetCode();
        //    fn_read_schdl();
        //    fn_HideDebugCtrls();
        // fn_SetCode();
        await scwin.search();
        $c.cm.PanelToGroupBox(panel_1);
        scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30604.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    if (scwin.gLdMktTp === "6") {
        // 코넥스 일경우 체크박스 2개 disabled 처리
        chb_CHRG_TP_CD2.setDisabled("true");
        checkbox_2.setDisabled("true");
        chb_CHRG_TP_CD3.setDisabled("true");
        checkbox_3.setDisabled("true");
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30604.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30604.img_Close_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert(trs_Save); ///('trs_Save.OnFail()');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30604.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert("수정하였습니다.");
        const fr_fn_Search = $c.frame.path("../").fn_tab1_Search;
        fr_fn_Search();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30604.trs_Save_OnSuccess" });
    }
};

