///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const parentWin = $c.frame.path("../");
    const paramObj = parentWin.gParamObj;
    if (paramObj === undefined) return;
    txb_ISUR_CD.setValue(paramObj.param1);
    txb_COM_NM.setValue(paramObj.param2);
    const vISUR_CD = txb_ISUR_CD.getValue();
    let vICHRG_TP_CD1 = "41";
    let vICHRG_TP_CD2 = "42";
    let vICHRG_TP_CD3 = "43";
    let vICHRG_TP_CD4 = "44";
    if (scwin.gLdMktTp === "6") {
        // 코넥스 일경우 변경
        let vICHRG_TP_CD1 = "81";
        let vICHRG_TP_CD2 = "";
        let vICHRG_TP_CD3 = "";
        let vICHRG_TP_CD4 = "82";
    }
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&CHRG_TP_CD=" + vICHRG_TP_CD1;
    url += "&SCREN_ID=" + "ULDSTF30604.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_CHRG1",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_CHRG1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    url += "&ISUR_CD=" + vISUR_CD;
    url += "&CHRG_TP_CD=" + vICHRG_TP_CD2;
    url += "&SCREN_ID=" + "ULDSTF30604.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions2 = {
        id : "sbm_dts_CHRG2",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_CHRG2=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    url += "&ISUR_CD=" + vISUR_CD;
    url += "&CHRG_TP_CD=" + vICHRG_TP_CD3;
    url += "&SCREN_ID=" + "ULDSTF30604.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions3 = {
