 */
scwin.control1 = function() {
    vCHRG_TP_CD1 = chb_CHRG_TP_CD1.getValue();
    if (vCHRG_TP_CD1 === "Y") {
        txb_DEP_NM1.setDisabled(false);
        txb_JOBTITL_NM1.setDisabled(false);
        txb_TEL_NO1.setDisabled(false);
        txb_CELLPHONE_NO1.setDisabled(false);
        txb_FAX_NO1.setDisabled(false);
        txb_EMAIL1.setDisabled(false);
        txb_LOC_ADDR1.setDisabled(false);
        txb_LOC_DTL_ADDR1.setDisabled(false);
    }
    if (vCHRG_TP_CD1 === "N") {
        txb_DEP_NM1.setDisabled(true);
