        txb_TEL_NO1.setDisabled(true);
        txb_CELLPHONE_NO1.setDisabled(true);
        txb_FAX_NO1.setDisabled(true);
        txb_EMAIL1.setDisabled(true);
        txb_LOC_ADDR1.setDisabled(true);
        txb_LOC_DTL_ADDR1.setDisabled(true);
    }
};

